use rayon::prelude::*;

let total: f64 = (0..n)
    .into_par_iter()                     // work-stealing workers
    .map(|i| compute_part(i))
    .sum();                              // rayon combines the partials

let mut set = tokio::task::JoinSet::new();
for i in 0..n {
    set.spawn(async move { compute_part(i).await });   // dispatch
}
let mut parts = Vec::with_capacity(n);
while let Some(res) = set.join_next().await { parts.push(res?); }  // join as they finish
let total: f64 = parts.into_iter().sum();              // combine

